-- =====================================================================
-- 045 — ZONES DE POLICE : LES 261 COMMUNES WALLONNES
--
-- Source : le découpage officiel des zones de police (BE.GAPD.ZO),
-- export du 18/06/2026, mention « Published in Royal Order ». C'est la
-- source primaire — celle qui fait foi — et non une compilation.
--
-- Elle corrige ce que la 044 laissait en blanc, et au passage ce que
-- les sources grand public racontent : plusieurs d'entre elles listent
-- des SECTIONS au lieu de communes. La zone des Fagnes y était donnée
-- pour six communes (Jalhay, La Reid, Polleur, Sart-lez-Spa, Spa,
-- Theux) alors qu'elle en couvre trois : Jalhay, Spa et Theux. La Reid
-- et Polleur dépendent de Theux, Sart-lez-Spa de Jalhay.
--
-- Le fichier suit les limites actuelles : la province de Luxembourg y
-- compte 43 communes et non 44, Bertogne ayant fusionné dans Bastogne
-- au 1er janvier 2025.
--
-- Répartition : Brabant wallon 27, Hainaut 69, Liège 84,
-- Luxembourg 43, Namur 38 — soit 261 communes et 71 zones.
--
-- Les noms de zones viennent de l'alias officiel, remis en casse
-- normale ; les accents sont repris des noms de communes du même
-- fichier plutôt que devinés. Le numéro de zone est conservé en note :
-- c'est lui qui identifie sans ambiguïté, pas le nom d'usage.
--
-- `zone_secours` n'est PAS touchée : elle reste renseignée pour la
-- province de Liège (044) et vide ailleurs, faute d'une source
-- équivalente pour les 34 zones de secours.
-- =====================================================================

begin;

on conflict (nom) do update set
  province = excluded.province,
  zone_police = excluded.zone_police,
  derniere_verification = excluded.derniere_verification,
  notes = case
            -- On ne réécrit pas une note déjà porteuse de la source
            -- officielle : la migration est rejouable sans empiler.
            when communes.notes like '%arrêté royal%' then communes.notes
            else trim(both ' ' from coalesce(communes.notes, '') || ' ' || excluded.notes)
          end;

commit;

