-- VÉRIFICATION
--   select province, count(*) communes, count(distinct zone_police) zones
--   from communes group by province order by province;
--   -- Brabant wallon 27/10, Hainaut 69/19, Liège 84/20,
--   -- Luxembourg 43/7, Namur 38/15
--
